// The single source of truth for every tool listed on CodeStack.
// `icon` is a Simple Icons slug. Run `npm run icons` after adding a new one.

export type Audience = "develop" | "design" | "ai"

export type CategoryId = "ai" | "code" | "server" | "devtools" | "cloud" | "design-tools" | "ui" | "type" | "media" | "web-tools" | "productivity"

export type SectionId =
  | "assistants" | "models" | "ai-coding" | "agents" | "ai-image" | "ai-video" | "ai-audio" | "ai-writing"
  | "frameworks" | "languages" | "mobile" | "docs-sites"
  | "backend" | "databases" | "data"
  | "editors" | "build" | "testing" | "docs-diagrams" | "web-css"
  | "hosting" | "services" | "payments"
  | "design-apps" | "ux" | "motion-3d" | "mockups"
  | "components" | "motion" | "inspiration"
  | "typography" | "color" | "icons"
  | "assets" | "stock-video" | "audio" | "3d"
  | "convert" | "media-tools" | "utilities" | "publishing"
  | "notes" | "files" | "work" | "privacy" | "life"

export interface Section {
  id: SectionId
  name: string
}

export interface Category {
  id: CategoryId
  name: string
  /** A shorter label for the Explore tabs, so every category fits on one line. */
  short: string
  audience: Audience
  /** Also listed under these audiences, e.g. web tools serve designers and developers alike. */
  alsoFor?: Audience[]
  tagline: string
  /** Sub-sections, shown as quick filters in Explore. Every tool belongs to one. */
  sections: Section[]
}

export interface Tool {
  name: string
  url: string
  description: string
  kind: string
  category: CategoryId
  section: SectionId
  icon?: string
  openSource?: boolean
  paid?: boolean
  /** Free tier with optional paid extras. */
  freemium?: boolean
  /** What the free tier includes, checked against the provider's own pricing page. */
  free?: string
}

const s = (id: SectionId, name: string): Section => ({ id, name })

