export const tools: Tool[] = [...coreTools, ...moreTools]

export const categoryById = Object.fromEntries(categories.map((c) => [c.id, c])) as Record<CategoryId, Category>

export function toolsIn(category: CategoryId) {
  return tools.filter((t) => t.category === category)
}

export function audienceOf(tool: Tool): Audience {
  return categoryById[tool.category].audience
}

/** Whether a category belongs in the Design, Develop or AI view, counting `alsoFor`. */
export function inAudience(category: Category, audience: Audience) {
  return category.audience === audience || !!category.alsoFor?.includes(audience)
}

export const sectionById = Object.fromEntries(categories.flatMap((c) => c.sections.map((s) => [s.id, { ...s, category: c.id }]))) as Record<
  SectionId,
  Section & { category: CategoryId }
>

