/** How a category is labelled by audience: "Design + Develop", "Design" or "Develop". */
export function audienceLabel(c: Category) {
  if (c.alsoFor?.length) return "Design + Develop"
  return c.audience === "design" ? "Design" : "Develop"
}

/** An Explore link for a category, optionally narrowed to one of its sections. */
export const exploreHref = (c: CategoryId, s?: SectionId) => `/explore?c=${c}${s ? `&s=${s}` : ""}`

export const stats = {
  tools: tools.length,
  categories: categories.length,
  developers: tools.filter((t) => inAudience(categoryById[t.category], "develop")).length,
  designers: tools.filter((t) => inAudience(categoryById[t.category], "design")).length,
}
